SELECT id, method, amount, MAX(amount) OVER (PARTITION BY status, method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_amount, MIN(amount) OVER (PARTITION BY status, method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_amount, SUM(amount) OVER (PARTITION BY status, method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_amount, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share FROM payments;
